add(13,'diagnostiek',['MD-grens 5,824; MDmax 10,863. Gevallen 1, 15, 41, 72, 93 en 112 zijn signalen; zonder aangetoonde fout blijven ze behouden.','MDmax 10,863 is kleiner dan 5,824, dus er zijn geen signalen.','De x-grens is ±3; alleen geval 57 is daarom een x-uitbijter.','Alle zes gevallen moeten automatisch worden verwijderd, ongeacht hun inhoud.'],'Beoordeel uitbijters in x met de Mahalanobis-afstanden.','x')
add(13,'diagnostiek',['Bij n = 178 geldt ±3. Het maximum 4,557 wijst op geval 57; zonder bijzondere oorzaak blijft de waarneming behouden.','Bij n = 178 geldt ±2 en ieder punt boven die grens moet worden verwijderd.','Omdat −1,885 boven −3 ligt, kunnen er ook aan de positieve kant geen uitbijters zijn.','De grens is 5,824; het residu 4,557 is dus niet opvallend.'],'Beoordeel uitbijters in y met de gestandaardiseerde residuen.','y')
add(14,'diagnostiek',['Cook-grens 0,062 en maximum 0,145 signaleren invloed. Onderzoek de gevallen en motiveer behandeling; een signaal alleen verplicht niet tot verwijderen.','Het maximum 0,145 ligt onder 0,062; er zijn geen invloedssignalen.','De Cook-grens is altijd 10, dus alle gevallen zijn zonder onderzoek bruikbaar.','Verwijder alle punten met een Cook-afstand groter dan nul.'])
add(15,'diagnostiek toetsen',['H₀: normale residuen. Bij n = 177 gebruikt de cursus KS; p = 0,001 < 0,05, dus H₀ verwerpen.','H₀: normale salarissen. Omdat p = 0,001 klein is, is normaliteit bewezen.','H₀: normale residuen. Bij p = 0,001 > 0,05 wordt H₀ niet verworpen.','De normaliteitstoets gaat over de verdeling van leeftijd en niet over residuen.'])
add(16,'diagnostiek toetsen',['ABSRES en Leeftijd: p < 0,001. Dit wijst op heteroscedasticiteit van de residuen.','Salaris en Leeftijd: een positieve correlatie bewijst homoscedasticiteit.','ABSRES en Leeftijd: p < 0,001 betekent dat hun samenhang ontbreekt.','Leeftijd en Vrouw: hun correlatie bepaalt de verdeling van de residuvariantie.'])
add(17,'diagnostiek transformaties',['Een passende transformatie/modelaanpassing en eventueel gewogen regressie; daarna opnieuw diagnostiek.','Alle residuen op nul zetten en daarna hetzelfde model blijven gebruiken.','De betrouwbaarheidsgrens veranderen totdat iedere toets niet-significant is.','Alle significante verklarende variabelen verwijderen zonder het model opnieuw te schatten.'])
add(18,'diagnostiek',['Onderzoek aantoonbare bijzondere oorzaken opnieuw, maar verwijder geen geldige gegevens om de normaliteitstoets te laten slagen.','Verwijder geval 57 altijd, ook als het een correcte waarneming is.','Verwijder net zo veel waarnemingen tot de p-waarde boven 0,05 komt.','Een normaliteitsprobleem kan nooit verband houden met opvallende residuen.'])
