add(22,'modelbouw',['Beoordeling (p = 0,179) valt als eerste af; daarna opnieuw schatten en beoordelen.','Leidinggevende valt als eerste af omdat deze de grootste coëfficiënt heeft.','Iedere variabele met p < 0,05 valt bij de eerste stap af.','Beoordeling verwijderen verandert gegarandeerd geen andere coëfficiënt of p-waarde.'])
add(23,'diagnostiek meervoudig',['VIFmax = 1,355 < 10; volgens de cursusgrens geen probleem met multicollineariteit.','VIFmax = 1,355 > 1; volgens de cursus is dat al ernstige multicollineariteit.','De VIF moet negatief zijn om multicollineariteit uit te sluiten.','Een significant model kan per definitie geen multicollineariteit bevatten.'])
add(24,'diagnostiek toetsen',['Volgens de cursuskeuze KS: p = 0,061 > 0,05, dus normale residuen niet verwerpen. Dit bewijst normaliteit niet; Shapiro-Wilk geeft een ander signaal.','p = 0,061 bewijst dat de residuen exact normaal verdeeld zijn.','p = 0,061 < 0,05, dus de KS-toets verwerpt normaliteit.','De toets gaat over het salaris zelf; de residuen zijn niet relevant.'])
add(25,'modelbouw validatie',['Voeg inhoudelijk passende voorspellers toe en valideer het model. Dat kan restvariatie verklaren, maar verandert de werkelijke salarissen niet.','Een hogere R² maakt de werkelijke lonen automatisch gelijk.','Voeg willekeurige voorspellers toe totdat de trainings-R² één is; validatie is dan overbodig.','Verwijder iedere werknemer met een ander salaris dan de voorspelling.'])
